mapper.select:
		select u.USER_ID, u.LOGONNAME, u.USER_NAME, u.LOGONTIME
		from [USER] u
		where u.ApproveStatus = 'Y'

			AND u.USER_ID = #{user_ID}


			AND u.USER_NAME like concat('%', #{user_NAME}, '%')


			AND u.LOGONTIME >= #{params.beginTime}


			AND u.LOGONTIME <= #{params.endTime}

		ORDER BY
			u.LOGONTIME ASC

-- 		${params.dataScope}
